export function sourceTitle(title,url){
 const text=String(title??'').trim();
 try{
  const parsed=new URL(url);
  const [law,section]=parsed.pathname.split('/').slice(1);
  if(text&&!genericTitles.has(text.toLocaleLowerCase('de'))&&!(section?.startsWith('art_')&&text.endsWith(' · Gesetzestext')))return text;
  if(sourceTitles[url])return sourceTitles[url];
  const host=parsed.hostname.replace(/^www\./,'');
  const provision=section?.match(/^(art_|__)([0-9]+[a-z]?)\.html$/);
  if(host==='gesetze-im-internet.de'&&lawNames[law]&&provision)return (provision[1]==='art_'?'Art. ':'§ ')+provision[2]+' '+lawNames[law];
  const identifier=decodeURIComponent(parsed.pathname.split('/').filter(Boolean).at(-1)??'').replace(/[-_]+/g,' ');
  return identifier?`${host} · ${identifier}`:host;
 }catch{return text;}
}
export function courtSourceLinks(source){
 if(Array.isArray(source.references))return source.references;
 const citation=[source.court,source.docket].filter(Boolean).join(' · ');
 return (source.links??[]).flatMap(url=>{
  try{
   const parsed=new URL(url);
   if(parsed.protocol!=='https:')return [];
   const host=parsed.hostname.replace(/^www\./,'');
   const law=host==='gesetze-im-internet.de'||host==='recht.nrw.de'||/eur-lex.*\/eli\//.test(url);
   const name=decisionHosts[host];
   return [{url,decision:!law&&!!name,title:(!law&&name)?citation+' · '+name:sourceTitle('',url)||host}];
  }catch{return [];}
 });
}
